import request from '@/utils/request';

export function loginUser(userName, passWord, captchaCode) {
    return request({
        url: '/login/pt_login',
        method: 'post',
        params: { userName, passWord, captcha_code: captchaCode },
    });
}

export function qqUserLogin(params) {
    return request({
        url: '/login/qq_login',
        method: 'post',
        params: params,
    });
}


// 注册用户
export function enrollUser(params) {
    return request({
        url: '/sys_user/enroll',
        method: 'post',
        params: params,
    });
}

// 找回密码
export function forgetPwd(params) {
    return request({
        url: '/sys_user/forgetPwd',
        method: 'post',
        params: params,
    });
}

// 修改密码
export function resetPWD(params) {
    return request({
        url: '/sys_user/resetPWD',
        method: 'post',
        params: params,
    });
}
